package com.campusconnect.service;
import com.campusconnect.dao.*; import com.campusconnect.model.*; import com.campusconnect.util.ValidationUtil; import java.time.LocalDate; import java.util.*;
public class LostFoundService { private final LostFoundDAO dao=new LostFoundDAO(); private final ClaimDAO claims=new ClaimDAO(); public List<LostFoundItem> all(String q,String cat){return dao.findAll(q,cat);} public void create(LostFoundItem x){ValidationUtil.required(x.getTitle(),"Title");ValidationUtil.required(x.getDescription(),"Description");ValidationUtil.required(x.getCategory(),"Category");ValidationUtil.required(x.getLocation(),"Location");if(x.getItemDate()==null)x.setItemDate(LocalDate.now());dao.insert(x);} public void claim(int item,int student){claims.insert(item,student);} public List<Claim> claims(int student){return student==0?claims.findAll():claims.findByStudent(student);} public void claimStatus(int id,String s){claims.updateStatus(id,s);} public void itemStatus(int id,String s){dao.updateStatus(id,s);} public void delete(int id){dao.delete(id);} public int lost(){return dao.count("Lost");} public int found(){return dao.count("Found");} }
